/* ============================================================
   PATCH 1.0.3 — редизайн карточки задачи (v4 FIX)
   ============================================================ */

#taskModal .modal-content {
    display: flex !important;
    flex-direction: column !important;
    max-height: 92vh !important;
    padding: 0 !important;
    overflow: hidden !important;
    border-radius: 16px;
}

/* Шапка */
#taskModal .task-modal-header {
    flex: 0 0 auto;
    padding: 20px 24px 14px;
    border-bottom: 1px solid var(--trk-card-border);
    background: var(--trk-modal-bg);
    z-index: 5;
}
#taskModal .task-modal-header h2 {
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    font-size: 1.15rem !important;
    color: var(--trk-text) !important;
    background: none !important;
    -webkit-text-fill-color: currentColor !important;
    text-align: left !important;
}
#taskModal .task-modal-summary {
    display: flex;
    flex-wrap: wrap;
    gap: 6px 14px;
    font-size: 0.8rem;
    color: var(--trk-meta);
    margin-top: 6px;
}

/* Скролл-зона */
#taskModal .task-modal-scroll {
    flex: 1 1 auto;
    overflow-y: auto;
    padding: 20px 24px;
    min-height: 0;
}
#taskModal .task-modal-scroll::-webkit-scrollbar { width: 8px; }
#taskModal .task-modal-scroll::-webkit-scrollbar-thumb {
    background: rgba(128, 128, 128, 0.3);
    border-radius: 4px;
}
#taskModal .task-modal-scroll::-webkit-scrollbar-thumb:hover {
    background: var(--trk-accent);
}

/* Футер */
#taskModal .modal-actions {
    flex: 0 0 auto;
    margin: 0 !important;
    padding: 16px 24px 20px !important;
    border-top: 1px solid var(--trk-card-border) !important;
    background: var(--trk-modal-bg) !important;
    display: flex !important;
    justify-content: flex-end !important;
    gap: 12px !important;
    z-index: 5;
}

/* Сетка 50/50 */
#taskModal .task-modal-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
    gap: 24px;
    align-items: start;
}
#taskModal .task-modal-col {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

@media (max-width: 900px) {
    #taskModal .task-modal-grid {
        grid-template-columns: 1fr !important;
        gap: 16px;
    }
}

/* Иконка + Название */
#taskModal .task-name-row {
    display: flex;
    align-items: stretch;
    gap: 10px;
}
#taskModal .task-icon-square {
    width: 46px;
    height: 46px;
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.6rem;
    background: var(--trk-input-bg);
    border: 1px solid var(--trk-input-border);
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.2s ease;
    box-shadow: 0 2px 6px rgba(0,0,0,0.05);
}
#taskModal .task-icon-square:hover {
    border-color: var(--trk-accent);
    transform: scale(1.05);
    box-shadow: 0 4px 12px rgba(245, 215, 110, 0.15);
}
#taskModal .task-name-row > .form-group {
    flex: 1 1 auto;
    margin: 0 !important;
}
#taskModal .task-name-row > .form-group input {
    height: 46px !important;
    font-size: 1rem !important;
    font-weight: 600 !important;
}
#taskModal .icon-picker-hint { display: none !important; }

/* Карточки секций */
#taskModal .task-section-card {
    background: var(--trk-hover-row);
    border: 1px solid var(--trk-card-border);
    border-radius: 12px;
    padding: 16px;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
#taskModal .task-section-card:hover {
    border-color: rgba(245, 215, 110, 0.4);
    box-shadow: 0 4px 16px rgba(0,0,0,0.06);
}
#taskModal .task-section-card > label {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--trk-meta);
    margin-bottom: 8px;
}

/* Статус */
#taskModal .task-status-head {
    display: flex;
    gap: 10px;
    align-items: center;
    margin-bottom: 12px;
}
#taskModal .task-status-head > select {
    flex: 1 1 auto;
    height: 38px;
    padding: 0 12px;
    border: 1px solid var(--trk-input-border);
    border-radius: 8px;
    background: var(--trk-input-bg);
    color: var(--trk-text);
    font-weight: 600;
    font-size: 0.9rem;
}
#taskModal .task-urgent-toggle {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 38px;
    padding: 0 14px;
    background: rgba(233, 30, 99, 0.08);
    border: 1px solid rgba(233, 30, 99, 0.3);
    border-radius: 8px;
    cursor: pointer;
    font-weight: 700;
    font-size: 0.85rem;
    color: #e91e63;
    transition: all 0.2s;
}
#taskModal .task-urgent-toggle input { margin: 0; cursor: pointer; }
#taskModal .task-urgent-toggle:has(input:checked) {
    background: rgba(233, 30, 99, 0.2);
    border-color: #e91e63;
}

/* Даты (включая завершение) */
#taskModal .task-status-dates {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}
#taskModal .task-status-dates > .form-group { margin: 0 !important; }
#taskModal .task-status-dates > .task-date-completed {
    grid-column: 1 / -1;
    display: block;
}

/* Сотрудники по командам */
#taskModal .task-team-group {
    margin-bottom: 12px;
    border-bottom: 1px dashed var(--trk-border-soft);
    padding-bottom: 12px;
}
#taskModal .task-team-group:last-child {
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
}
#taskModal .task-team-title {
    font-size: 0.7rem;
    font-weight: 800;
    color: var(--trk-accent);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
}
#taskModal .assignees-item {
    padding: 6px 8px !important;
    border-radius: 8px !important;
    margin-bottom: 2px !important;
    transition: background 0.15s;
}
#taskModal .assignees-item:hover {
    background: var(--trk-filter-active-bg) !important;
}

/* Увеличенная высота Назначено */
#taskModal #taskAssigneesList {
    max-height: 450px !important;
    min-height: 250px;
    overflow-y: auto;
}

/* Спойлеры для Приказов и Ссылок */
#taskModal details.task-section {
    background: var(--trk-hover-row);
    border: 1px solid var(--trk-card-border);
    border-radius: 12px;
    margin-bottom: 12px;
    overflow: hidden;
}
#taskModal details.task-section > summary {
    cursor: pointer;
    padding: 12px 16px;
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--trk-text);
    list-style: none;
    display: flex;
    align-items: center;
    gap: 8px;
    user-select: none;
    transition: background 0.2s;
}
#taskModal details.task-section > summary:hover {
    background: rgba(245, 215, 110, 0.06);
}
#taskModal details.task-section > summary::-webkit-details-marker { display: none; }
#taskModal details.task-section > summary::before {
    content: '▶';
    font-size: 0.65em;
    color: var(--trk-meta);
    transition: transform 0.2s ease;
}
#taskModal details.task-section[open] > summary::before {
    transform: rotate(90deg);
}
#taskModal details.task-section > summary .cnt {
    margin-left: auto;
    font-size: 0.7rem;
    padding: 2px 8px;
    border-radius: 8px;
    background: var(--trk-filter-active-bg);
    color: var(--trk-filter-active);
    font-weight: 800;
}
#taskModal details.task-section > .task-section-body {
    padding: 0 16px 16px;
}

/* Логи (внизу) */
#taskModal .task-logs-card {
    background: var(--trk-hover-row);
    border: 1px solid var(--trk-card-border);
    border-radius: 12px;
    padding: 16px;
}
#taskModal .task-logs-card label {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--trk-meta);
    margin-bottom: 8px;
}
#taskModal #task_folder.task-folder-readonly {
    width: 100%;
    min-height: 120px !important;
    max-height: 200px !important;
    overflow-y: auto !important;
    resize: vertical;
    background: rgba(128, 128, 128, 0.04) !important;
    color: var(--trk-meta) !important;
    cursor: default !important;
    border: 1px solid var(--trk-border-soft) !important;
    border-radius: 8px;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: 0.8rem;
    line-height: 1.5;
    white-space: pre-wrap;
    box-sizing: border-box;
}
#taskModal .task-folder-hint {
    font-size: 0.72rem;
    color: var(--trk-meta);
    margin-top: 6px;
    font-style: italic;
}

/* Светлая тема */
body.trk-theme-light #taskModal .task-icon-square {
    background: #ffffff;
}
body.trk-theme-light #taskModal .task-section-card,
body.trk-theme-light #taskModal .task-logs-card {
    background: #f7f9fa;
}

/* ============================================================
   PATCH 1.0.3 — редизайн карточки задачи (v4 FIX)
   ============================================================ */
(function(){
'use strict';
if (window.__trkTaskModalCoolV103) return;
window.__trkTaskModalCoolV103 = true;

function $(id){ return document.getElementById(id); }

function _findGroup(el){
    if (!el) return null;
    return el.closest ? el.closest('.form-group') : null;
}

function _restructure(){
    var m = $('taskModal');
    if (!m || !m.classList.contains('active')) return;
    var content = m.querySelector('.modal-content');
    if (!content) return;

    if (content.querySelector('.task-modal-grid')) return;

    // 1. Создаём каркас
    var hdr = document.createElement('div');
    hdr.className = 'task-modal-header';
    var h2 = content.querySelector('h2') || content.querySelector('#taskModalTitle');
    if (h2) hdr.appendChild(h2);

    var sc = document.createElement('div');
    sc.className = 'task-modal-scroll';
    var grid = document.createElement('div');
    grid.className = 'task-modal-grid';
    var main = document.createElement('div');
    main.className = 'task-modal-col task-modal-col-main';
    var side = document.createElement('div');
    side.className = 'task-modal-col task-modal-col-side';
    grid.appendChild(main);
    grid.appendChild(side);
    sc.appendChild(grid);

    var actions = content.querySelector('.modal-actions');

    // 2. Переносим все формы
    var allGroups = Array.from(content.querySelectorAll('.form-group'));
    allGroups.forEach(function(g){
        if (g.querySelector('#taskDepartmentsList') || g.querySelector('#taskAssigneesList')) {
            side.appendChild(g);
        } else {
            main.appendChild(g);
        }
    });

    // 3. Удаляем старые обёртки
    Array.from(content.children).forEach(function(child){
        if (child !== h2 && child !== actions && child !== hdr && child !== sc) {
            content.removeChild(child);
        }
    });
    content.insertBefore(hdr, content.firstChild);
    content.insertBefore(sc, actions || null);

    _applyLayout();
}

function _applyLayout(){
    var content = document.querySelector('#taskModal .modal-content');
    if (!content) return;
    var main = content.querySelector('.task-modal-col-main');
    var side = content.querySelector('.task-modal-col-side');

    // 1. Иконка и название в одну строку
    var gIcon = _findGroup($('taskIconPickBtn'));
    var gName = _findGroup($('task_name'));
    if (gIcon && gName && !main.querySelector('.task-name-row')) {
        var row = document.createElement('div');
        row.className = 'task-name-row';

        var iconBtn = $('taskIconPickBtn');
        if (iconBtn) {
            iconBtn.className = 'task-icon-square';
            var hint = iconBtn.querySelector('.icon-picker-hint');
            if (hint) hint.remove();
            row.appendChild(iconBtn);
        }

        var label = gName.querySelector('label');
        if (label) label.remove();
        row.appendChild(gName);

        main.insertBefore(row, gIcon);
        gIcon.remove();
    }

    // 2. Карточки Описания и Тегов
    ['task_description', 'taskTagsBox'].forEach(function(id){
        var g = _findGroup($(id));
        if (g && !g.classList.contains('task-section-card')) {
            g.classList.add('task-section-card');
        }
    });

    // 3. Сборка блока Состояние (в правую колонку, самым первым)
    var gStatus = _findGroup($('task_status'));
    if (gStatus && !gStatus.querySelector('.task-status-card')) {
        gStatus.classList.add('task-section-card');
        var card = document.createElement('div');
        card.className = 'task-status-card';

        var head = document.createElement('div');
        head.className = 'task-status-head';
        var sel = $('task_status');
        if (sel) head.appendChild(sel);
        var uWrap = $('task_is_urgent') ? $('task_is_urgent').closest('.task-urgent-toggle') : null;
        if (uWrap) head.appendChild(uWrap);
        card.appendChild(head);

        var dates = document.createElement('div');
        dates.className = 'task-status-dates';
        var gSd = _findGroup($('task_start_date'));
        var gDl = _findGroup($('task_deadline'));
        var gCmp = _findGroup($('task_completed_at'));
        if (gSd) dates.appendChild(gSd);
        if (gDl) dates.appendChild(gDl);

        // ВАЖНО: Дата завершения НЕ скрывается, а добавляется в сетку
        if (gCmp) {
            gCmp.classList.add('task-date-completed');
            dates.appendChild(gCmp);
        }
        card.appendChild(dates);

        gStatus.innerHTML = '';
        var lbl = document.createElement('label');
        lbl.textContent = 'Состояние';
        gStatus.appendChild(lbl);
        gStatus.appendChild(card);

        // Переносим в правую колонку в самое начало
        if (side.firstChild) {
            side.insertBefore(gStatus, side.firstChild);
        } else {
            side.appendChild(gStatus);
        }
    }

    // 4. Сотрудники по командам
    var asgList = $('taskAssigneesList');
    if (asgList && asgList.parentNode && !asgList.parentNode.querySelector('.task-team-group')) {
        var st = window.__trkState || {};
        var teams = st.teams || [];
        var emps = st.employees || [];
        var teamMap = {};

        teams.forEach(function(t){
            var members = t.member_ids || [];
            if (t.manager_id && members.indexOf(t.manager_id) === -1) members.push(t.manager_id);
            teamMap[t.name] = members;
        });

        var grouped = {};
        var ungrouped = [];
        emps.forEach(function(e){
            if (!e.id) return;
            var found = false;
            for (var tName in teamMap) {
                if (teamMap[tName].indexOf(e.id) !== -1) {
                    if (!grouped[tName]) grouped[tName] = [];
                    grouped[tName].push(e);
                    found = true;
                }
            }
            if (!found) ungrouped.push(e);
        });

        var oldInputs = asgList.querySelectorAll('input[type="checkbox"]');
        var selectedIds = [];
        oldInputs.forEach(function(inp){ if (inp.checked) selectedIds.push(inp.value); });
        asgList.innerHTML = '';

        for (var tName in grouped) {
            var grp = document.createElement('div');
            grp.className = 'task-team-group';
            grp.innerHTML = '<div class="task-team-title">👥 ' + tName + '</div>';
            grouped[tName].forEach(function(e){
                grp.appendChild(_makeCheckbox(e, selectedIds.indexOf(e.id) !== -1));
            });
            asgList.appendChild(grp);
        }
        if (ungrouped.length) {
            var grpU = document.createElement('div');
            grpU.className = 'task-team-group';
            grpU.innerHTML = '<div class="task-team-title">👤 Без команды</div>';
            ungrouped.forEach(function(e){
                grpU.appendChild(_makeCheckbox(e, selectedIds.indexOf(e.id) !== -1));
            });
            asgList.appendChild(grpU);
        }
    }

    // 5. Приказы и Ссылки в спойлеры <details>
    ['taskOrdersGroup', 'taskLinksGroup'].forEach(function(gid){
        var grp = $(gid);
        if (grp && !grp.querySelector('details')) {
            var title = (gid === 'taskOrdersGroup') ? '📄 Приказы / распоряжения' : '🔗 Ссылки';
            var details = document.createElement('details');
            details.className = 'task-section';
            details.innerHTML = '<summary>' + title + ' <span class="cnt"></span></summary><div class="task-section-body"></div>';
            var body = details.querySelector('.task-section-body');
            while (grp.firstChild) body.appendChild(grp.firstChild);
            grp.appendChild(details);
            var count = grp.querySelectorAll('.task-link-row').length;
            details.querySelector('.cnt').textContent = count > 0 ? count : '';
            if (count > 0) details.open = true;
            if (grp.parentNode !== main) main.appendChild(grp);
        }
    });

    // 6. Логи в самый низ (без сворачивания, с прокруткой)
    var gFolder = _findGroup($('task_folder'));
    if (gFolder && !gFolder.classList.contains('task-logs-card')) {
        gFolder.className = 'task-logs-card';
        var lbl2 = gFolder.querySelector('label');
        if (lbl2) lbl2.textContent = '📄 Логи (Доп. данные)';

        var f = $('task_folder');
        if (f) {
            f.readOnly = true;
            f.classList.add('task-folder-readonly');
        }
        if (!gFolder.querySelector('.task-folder-hint')) {
            var hint = document.createElement('div');
            hint.className = 'task-folder-hint';
            hint.textContent = 'Обновляется автоматически при сохранении отметок.';
            gFolder.appendChild(hint);
        }
        main.appendChild(gFolder); // В самый низ
    }
}

function _makeCheckbox(e, checked) {
    var lbl = document.createElement('label');
    lbl.className = 'assignees-item';
    lbl.innerHTML = '<input type="checkbox" value="' + e.id + '"' + (checked ? ' checked' : '') + '>'
        + '<span class="assignees-dot" style="background:' + (e.color || '#888') + ';"></span>'
        + '<span class="assignees-name">' + (e.name || e.id) + '</span>';
    return lbl;
}

function _hook(){
    var m = $('taskModal');
    if (!m) return false;
    if (!m._v103coolObs) {
        m._v103coolObs = true;
        new MutationObserver(function(){
            if (m.classList.contains('active')) {
                setTimeout(function(){ _restructure(); }, 50);
            }
        }).observe(m, { attributes: true, attributeFilter: ['class'] });
    }
    return true;
}

function boot(){
    if (!_hook()) { setTimeout(boot, 300); return; }
    if ($('taskModal').classList.contains('active')) { _restructure(); }
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
